{
  "tasks": [
    {
      "task_id": "T01",
      "title": "各城市已完成订单销售额总和及降序排名",
      "business_question": "按城市计算已完成订单的销售额总和，并按总和降序排列。仅分析已完成订单。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标“按城市计算已完成订单的销售额总和”，并满足所有约束条件（筛选、指标、排序）。删除此任务将无法获得核心决策依据。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0003",
                "alias": "total_sales"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "total_sales",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
